// A brief of the given type with nothing in it but what a draft's check and render need.
export function standInBrief(jobId: string, key: string, type: DraftType): ArtifactBrief {
  return {
    version: 1,
    job_id: jobId,
    key,
    name: `${key} work`,
    slug: key,
    artifact_type: type,
    definition: 'Confirming the day schedules with the pipeline.',
    synthesis: { description: 'The desk confirms each schedule.', steps: ['Confirm it'], stalls: [], contradictions: [], approach: 'A checklist.', rationale: 'It repeats.' },
    counted: {
      label: 'facts counted by the pipeline',
      occurrences: 4,
      active_months: 2,
      first_day: '2001-01-15',
      last_day: '2001-03-15',
      messages: 5,
      staff_participants: 2,
      actions: { short: 3, medium: 1, long: 0, forwards: 1, chasers: 0, reads: 6 },
      stalls: { waiting_on_reply: 0, rework: 0, handoff_confusion: 0, ownership_conflict: 0, avoidance: 0, system_failure: 0, other: 0 },
    },
    participants: [{ name: 'Ann Lee', kind: 'person', staff: true, authored: 3, forwards: 1, chasers: 0, reads: 2 }],
    ownership: { claims: [], conflicts: 0 },
    estimate: null,
    evidence: [{ id: 'batch-000:e0', message_id: 'corpus/m5/inbox/01', date: '2001-01-15', sender: 'Ann Lee', role: 'request', quote: 'Please handle the schedule for the desk today.' }],
    stall_quotes: [],
    ownership_quotes: [],
  };
}
export const standInBriefText = (jobId: string, key: string, type: DraftType): string => briefText(standInBrief(jobId, key, type));
